// csv (multi="mult") delivers one message whose payload is the array of ALL rows
// currently in the file, not one message per row — so both the fan-out into individual
// records and the "grep" happen right here.
//
// The namespace holds one LatestWorkOrder per functional location, not one topic per
// order, so: group by functional_location keeping the last (most recently created) row,
// then only pass it on if that location's latest order id has actually changed since the
// last time this flow published for it.
const rows = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const latestByLocation = {};
for (const row of rows) {
    if (!row || !row.functional_location || !row.order_id) continue;
    latestByLocation[row.functional_location] = row; // later rows overwrite earlier ones
}

const lastPublished = flow.get("lastOrderIdByLocation") || {};
const fresh = [];
for (const [location, row] of Object.entries(latestByLocation)) {
    if (lastPublished[location] === row.order_id) continue;
    lastPublished[location] = row.order_id;
    fresh.push({ payload: row });
}
flow.set("lastOrderIdByLocation", lastPublished);
return [fresh];

// Functional-location code -> namespace path segment, mirroring the topic tree the
// simulator already publishes live process data under (see CLAUDE.md "Topic naming").
// Source of truth for the codes themselves: WORK_ORDER_META in simulator.py.
const FL_PATH = {
    "WL01-ING": "IngredientHandling",
    "WL01-MIX": "BatterMixing",
    "WL01-PRF": "Proofing",
    "WL01-OVN-Z1": "Oven/HeatingZone01",
    "WL01-OVN-Z2": "Oven/HeatingZone02",
    "WL01-OVN-AIR": "Oven/AirCirculation",
    "WL01-OVN-HUM": "Oven/HumidityControl",
    "WL01-OVN-BDM": "Oven/BeltDriveModule",
    "WL01-OVN-UTL": "Oven/OvenUtilityMetering",
    "WL01-COOL": "Cooling",
    "WL01-PACK": "Packaging",
};

const LINE_PREFIX = "v1.0/SHT/Munich/Maintenance/WaffleLine01";
const row = msg.payload;
const flPath = FL_PATH[row.functional_location] || row.functional_location || "Unknown";

msg.topic = `${LINE_PREFIX}/${flPath}/LatestWorkOrder`;
msg.payload = JSON.stringify({
    domain: "maintenance",
    functionalLocation: row.functional_location,
    orderId: row.order_id,
    orderType: row.order_type,
    priority: row.priority,
    workCenter: row.work_center,
    shortText: row.short_text,
    breakdown: row.breakdown === true || row.breakdown === "True" || row.breakdown === "true",
    reportedBy: row.reported_by,
    status: row.status,
    createdAt: row.created_at,
    timestamp: new Date().toISOString(),
});
return msg;

// csv (multi="mult") delivers one message whose payload is the array of ALL rows
// currently in the file — the fan-out into individual records, the stage filter, and the
// "grep" for ones not seen before all happen right here.
//
// This branch only handles Proofing so far; Oven-stage rows are left for a later branch.
const rows = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const seen = flow.get("seenProofingSampleIds") || {};
const fresh = [];

for (const row of rows) {
    const id = row && row.sample_id;
    if (!id || row.stage !== "Proofing" || seen[id]) continue;
    seen[id] = true;
    fresh.push({ payload: row });
}
flow.set("seenProofingSampleIds", seen);
return [fresh];

const LINE_PREFIX = "v1.0/SHT/Munich/Quality/WaffleLine01/Proofing";
const row = msg.payload;
const ts = new Date().toISOString();
const num = (v) => (v === "" || v == null ? null : Number(v));
const bool = (v) => v === true || v === "True" || v === "true";

const tempMsg = {
    topic: `${LINE_PREFIX}/DoughCoreTemperature`,
    payload: JSON.stringify({ value: num(row.doughTemp), unit: "\u00b0C", timestamp: ts }),
};
const phMsg = {
    topic: `${LINE_PREFIX}/DoughPh`,
    payload: JSON.stringify({ value: num(row.doughPh), unit: "pH", timestamp: ts }),
};
const latestMsg = {
    topic: `${LINE_PREFIX}/LatestSample`,
    payload: JSON.stringify({
        domain: "quality",
        stage: "Proofing",
        sampleId: row.sample_id,
        adhoc: bool(row.adhoc),
        doughCoreTemperature: num(row.doughTemp),
        doughPh: num(row.doughPh),
        proofHeight: num(row.proofHeight),
        visualCheck: row.visual_check,
        result: row.result,
        note: row.note,
        technician: row.technician,
        completedAt: row.completed_at,
        timestamp: ts,
    }),
};

return [[tempMsg, phMsg, latestMsg]];
